// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public {
        c = new ModifierEntrancy();
    }

    function testFuzz_property(address actor) public {
        // Adversarial counterparty: actor must be a Bank-like contract
        // that returns the correct supportsToken() hash, since c checks
        // keccak256("Nu Token") == Bank(msg.sender).supportsToken().
        vm.assume(actor != address(0));
        vm.assume(uint160(actor) > 0x100);

        Bank bank = new Bank();
        address caller = address(bank);

        uint256 beforeBal = c.tokenBalance(caller);

        // caller must have no balance (admissible domain)
        vm.assume(beforeBal == 0);

        // Call airDrop from the Bank contract. Since Bank has no airDrop
        // fallback, we use vm.prank with a low-level call. However, c
        // checks msg.sender, so we need the Bank to call airDrop.
        // Bank has no code to call, so instead we use vm.prank on the
        // bank address and call c directly: prank sets msg.sender to
        // the bank address even though the EOA has no code.
        vm.prank(caller);
        c.airDrop();

        uint256 afterBal = c.tokenBalance(caller);

        assertTrue(afterBal == beforeBal + 20);
    }
}
